WITH base AS (SELECT id, order_id, method, amount, paid_at, status, CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'Group A' ELSE 'Other' END status_group, COALESCE(method, 'N/A') resolved_method FROM payments WHERE order_id IS NOT NULL AND method != 'card') SELECT CASE WHEN amount >= 1400 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_rows, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE method = 'bank_transfer') AS bank_transfer_rows, SIZE(COLLECT_SET(status)) AS num_status_2, APPROX_PERCENTILE(amount, 0.9) AS amount_p90, AVG(amount) FILTER (WHERE status = 'FAILED') AS failed_avg_amount FROM base GROUP BY CASE WHEN amount >= 1400 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', paid_at) HAVING bank_transfer_rows > 1 ORDER BY num_status_2 DESC
